#!/usr/bin/env python3
import struct,sys,zipfile
jar='/opt/maelstrom/lib/maelstrom.jar'

def parse_cp(data, off):
    count=struct.unpack_from('>H',data,off)[0]; off+=2
    cp=[None]*count; i=1
    while i<count:
        tag=data[off]; off+=1
        if tag==1:
            n=struct.unpack_from('>H',data,off)[0]; off+=2
            cp[i]=('Utf8',data[off:off+n].decode('utf-8','replace')); off+=n
        elif tag in (3,4): cp[i]=('Num',struct.unpack_from('>i' if tag==3 else '>f',data,off)[0]); off+=4
        elif tag in (5,6): cp[i]=('Long',struct.unpack_from('>q',data,off)[0]); off+=8; i+=1
        elif tag in (7,8,16,19,20): cp[i]=({7:'Class',8:'String',16:'MethodType',19:'Module',20:'Package'}[tag],struct.unpack_from('>H',data,off)[0]); off+=2
        elif tag in (9,10,11,12,17,18): cp[i]=({9:'Field',10:'Method',11:'IField',12:'IMethod',17:'Dyn',18:'InvokeDyn'}[tag],struct.unpack_from('>HH',data,off)); off+=4
        elif tag==15: cp[i]=('MH',struct.unpack_from('>BH',data,off)); off+=3
        else: raise Exception((tag,i,off))
        i+=1
    return cp,off

def attrs(data,off,cp):
    n=struct.unpack_from('>H',data,off)[0]; off+=2
    out=[]
    for _ in range(n):
        ni,l=struct.unpack_from('>HI',data,off); off+=6
        out.append((ni,data[off:off+l])); off+=l
    return out,off

def member(data,off,cp):
    acc,ni,di=struct.unpack_from('>HHH',data,off); off+=6
    aa,off=attrs(data,off,cp)
    return (acc,cp[ni][1],cp[di][1],aa),off

def cpstr(cp,i):
    if i==0 or cp[i] is None:return '#0'
    e=cp[i]; t=e[0]
    if t=='Utf8':return e[1]
    if t=='Class':return cpstr(cp,e[1])
    if t=='String':return repr(cpstr(cp,e[1]))
    if t=='NameAndType':return cpstr(cp,e[1][0])+':'+cpstr(cp,e[1][1])
    if t in ('Field','Method','IField','IMethod'):return cpstr(cp,e[1][0])+'.'+cpstr(cp,e[1][1])
    if t=='InvokeDyn':return 'InvokeDyn#'+str(e[1][0])+' '+cpstr(cp,e[1][1])
    if t=='Dyn':return 'Dyn#'+str(e[1][0])
    if t=='Long':return str(e[1])
    if t=='Num':return str(e[1])
    return repr(e)

